using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace Editor
{
    [InitializeOnLoad]
    public static class BootScenePlayMode
    {
        // Flag to avoid re-entrancy
        static bool _sProcessed;
        // Store the scene paths that were open before we changed them
        static string[] _sPreviousScenePaths;

        static BootScenePlayMode()
        {
            EditorApplication.playModeStateChanged += OnPlayModeStateChanged;
        }

        static void OnPlayModeStateChanged(PlayModeStateChange state)
        {
            if (state == PlayModeStateChange.ExitingEditMode)
            {
                // About to enter Play mode in Editor
                if (_sProcessed) return;
                _sProcessed = true;

                // Ask user to save modified scenes; if they cancel, abort entering play mode
                if (!UnityEditor.SceneManagement.EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
                {
                    EditorApplication.isPlaying = false;
                    _sProcessed = false;
                    return;
                }

                // Find the _Boot scene asset
                string bootPath = FindBootScenePath();
                if (string.IsNullOrEmpty(bootPath))
                {
                    Debug.LogWarning("[BootScenePlayMode] Could not find a scene named '_Boot' in the project. Play will continue normally.");
                    _sProcessed = false;
                    return;
                }

                // Store currently open scenes so we can restore them later
                int sceneCount = UnityEditor.SceneManagement.EditorSceneManager.sceneCount;
                List<string> openPaths = new List<string>(sceneCount);
                var active = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
                string activePath = active.path;

                for (int i = 0; i < sceneCount; i++)
                {
                    var s = UnityEditor.SceneManagement.EditorSceneManager.GetSceneAt(i);
                    if (!string.IsNullOrEmpty(s.path)) openPaths.Add(s.path);
                }

                _sPreviousScenePaths = openPaths.ToArray();

                // Open the boot scene first (single)
                UnityEditor.SceneManagement.EditorSceneManager.OpenScene(bootPath, OpenSceneMode.Single);

                // Re-open previous scenes additively (skip boot if it was already in the list)
                bool bootWasOriginallyOpen = false;
                foreach (var p in _sPreviousScenePaths)
                {
                    if (string.IsNullOrEmpty(p)) continue;
                    if (p == bootPath) { bootWasOriginallyOpen = true; continue; }
                    UnityEditor.SceneManagement.EditorSceneManager.OpenScene(p, OpenSceneMode.Additive);
                }

                // Restore the previously active scene if possible
                if (!string.IsNullOrEmpty(activePath))
                {
                    var prevActive = UnityEditor.SceneManagement.EditorSceneManager.GetSceneByPath(activePath);
                    if (prevActive.IsValid()) UnityEditor.SceneManagement.EditorSceneManager.SetActiveScene(prevActive);
                }

                // If boot wasn't originally open we can close it now so it doesn't remain loaded during Play
                if (!bootWasOriginallyOpen)
                {
                    var bootScene = UnityEditor.SceneManagement.EditorSceneManager.GetSceneByPath(bootPath);
                    if (bootScene.IsValid()) UnityEditor.SceneManagement.EditorSceneManager.CloseScene(bootScene, true);
                }
            }
            else if (state == PlayModeStateChange.EnteredEditMode)
            {
                // We returned to Edit mode after stopping Play. Restore previous open scenes if we modified them.
                if (!_sProcessed) return;
                _sProcessed = false;

                if (_sPreviousScenePaths == null || _sPreviousScenePaths.Length == 0) return;

                // If the editor already has the same scenes open, do nothing
                bool same = UnityEditor.SceneManagement.EditorSceneManager.sceneCount == _sPreviousScenePaths.Length;
                if (same)
                {
                    for (int i = 0; i < _sPreviousScenePaths.Length; i++)
                    {
                        var sc = UnityEditor.SceneManagement.EditorSceneManager.GetSceneAt(i);
                        if (sc.path != _sPreviousScenePaths[i]) { same = false; break; }
                    }
                }
                if (same)
                {
                    _sPreviousScenePaths = null;
                    return;
                }

                // Open the saved scenes: first as Single then others Additive
                UnityEditor.SceneManagement.EditorSceneManager.OpenScene(_sPreviousScenePaths[0], OpenSceneMode.Single);
                for (int i = 1; i < _sPreviousScenePaths.Length; i++)
                {
                    if (string.IsNullOrEmpty(_sPreviousScenePaths[i])) continue;
                    UnityEditor.SceneManagement.EditorSceneManager.OpenScene(_sPreviousScenePaths[i], OpenSceneMode.Additive);
                }

                // Set active to the first previous scene
                var first = UnityEditor.SceneManagement.EditorSceneManager.GetSceneByPath(_sPreviousScenePaths[0]);
                if (first.IsValid()) UnityEditor.SceneManagement.EditorSceneManager.SetActiveScene(first);

                _sPreviousScenePaths = null;
            }
        }

        static string FindBootScenePath()
        {
            // Try to find a scene asset named exactly "_Boot"
            string[] guids = AssetDatabase.FindAssets("_Boot t:Scene");
            foreach (var g in guids)
            {
                string path = AssetDatabase.GUIDToAssetPath(g);
                if (System.IO.Path.GetFileNameWithoutExtension(path) == "_Boot") return path;
            }

            // Fallback: search all scenes for name match (case-insensitive)
            guids = AssetDatabase.FindAssets("t:Scene");
            foreach (var g in guids)
            {
                string path = AssetDatabase.GUIDToAssetPath(g);
                if (System.IO.Path.GetFileNameWithoutExtension(path).Equals("_Boot", System.StringComparison.OrdinalIgnoreCase)) return path;
            }

            return null;
        }
    }
}

using UnityEngine;
using UnityEngine;

public class AudioManager : MonoBehaviour
{
    #region Singleton
    public static AudioManager instance;

    private void Awake()
    {
        if (instance == null)
        {
            instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }
    #endregion
}

using System.Collections.Generic;
using UnityEngine;

public class AudioManager : MonoBehaviour
{
    #region Singleton
    public static AudioManager Instance { get; private set; }
    [System.Obsolete("Use Instance instead", false)]
    public static AudioManager instance => Instance;

    private void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
            return;
        }

        EnsureSystemSource();
        if (activeSources == null) activeSources = new List<AudioSource>();
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }
    #endregion

    [Header("Audio References")]
    [SerializeField]
    // single AudioSource used for 2D sounds and one-shots
    private AudioSource systemSource;

    [SerializeField]
    // parent transform for created 3D sources
    private Transform activeSourceParent;

    // list of active 3D looping AudioSources
    private List<AudioSource> activeSources = new List<AudioSource>();

    void EnsureSystemSource()
    {
        if (systemSource == null)
        {
            GameObject go = new GameObject("SystemAudioSource");
            go.transform.SetParent(transform);
            systemSource = go.AddComponent<AudioSource>();
            systemSource.playOnAwake = false;
            systemSource.spatialBlend = 0f; // 2D
        }

        if (activeSourceParent == null) activeSourceParent = transform;
    }

    // ------------------ 2D Sound API (systemSource) ------------------
    public void Play2D(AudioClip clip, float volume = 1f, bool loop = false)
    {
        if (clip == null) return;
        EnsureSystemSource();

        if (loop)
        {
            systemSource.clip = clip;
            systemSource.loop = true;
            systemSource.volume = volume;
            systemSource.Play();
        }
        else
        {
            systemSource.PlayOneShot(clip, volume);
        }
    }

    public void Play2DOneShot(AudioClip clip, float volume = 1f)
    {
        if (clip == null) return;
        EnsureSystemSource();
        systemSource.PlayOneShot(clip, volume);
    }

    public void Stop2D()
    {
        if (systemSource == null) return;
        systemSource.Stop();
        systemSource.clip = null;
        systemSource.loop = false;
    }

    public void Pause2D()
    {
        if (systemSource == null) return;
        systemSource.Pause();
    }

    public void Resume2D()
    {
        if (systemSource == null) return;
        systemSource.UnPause();
    }

    // ------------------ 3D Sound API (activeSources) ------------------
    // Plays a 3D clip at the given position. If loop==true the created AudioSource is tracked in activeSources and must be stopped explicitly.
    public AudioSource Play3D(AudioClip clip, Vector3 position, float volume = 1f, bool loop = false, float minDistance = 1f, float maxDistance = 500f)
    {
        if (clip == null) return null;

        GameObject go = new GameObject("3DAudio_" + clip.name);
        go.transform.position = position;
        go.transform.SetParent(activeSourceParent, true);

        AudioSource src = go.AddComponent<AudioSource>();
        src.spatialBlend = 1f; // full 3D
        src.playOnAwake = false;
        src.clip = clip;
        src.volume = volume;
        src.loop = loop;
        src.minDistance = minDistance;
        src.maxDistance = maxDistance;
        src.rolloffMode = AudioRolloffMode.Logarithmic;
        src.Play();

        if (loop)
        {
            if (activeSources == null) activeSources = new List<AudioSource>();
            activeSources.Add(src);
        }
        else
        {
            // schedule destruction when finished
            Destroy(go, clip.length + 0.1f);
        }

        return src;
    }

    // Play a 3D one-shot (does not create a tracked AudioSource)
    public void Play3DOneShot(AudioClip clip, Vector3 position, float volume = 1f)
    {
        if (clip == null) return;
        AudioSource.PlayClipAtPoint(clip, position, volume);
    }

    public void Stop3D(AudioSource source, bool destroy = true)
    {
        if (source == null) return;
        source.Stop();
        if (activeSources != null) activeSources.Remove(source);
        if (destroy) Destroy(source.gameObject);
        else
        {
            source.clip = null;
            source.loop = false;
        }
    }

    public void Pause3D(AudioSource source)
    {
        if (source == null) return;
        source.Pause();
    }

    public void Resume3D(AudioSource source)
    {
        if (source == null) return;
        source.UnPause();
    }

    public void StopAll3D()
    {
        if (activeSources == null) return;
        // make a copy to avoid modification during iteration
        var copy = new List<AudioSource>(activeSources);
        foreach (var s in copy)
        {
            if (s != null) Stop3D(s, true);
        }
        activeSources.Clear();
    }

    public void PauseAll3D()
    {
        if (activeSources == null) return;
        foreach (var s in activeSources)
        {
            if (s != null) s.Pause();
        }
    }

    public void ResumeAll3D()
    {
        if (activeSources == null) return;
        foreach (var s in activeSources)
        {
            if (s != null) s.UnPause();
        }
    }

    // Optional static convenience wrappers
    public static void Play2DStatic(AudioClip clip, float volume = 1f, bool loop = false) { if (Instance != null) Instance.Play2D(clip, volume, loop); }
    public static void Play2DOneShotStatic(AudioClip clip, float volume = 1f) { if (Instance != null) Instance.Play2DOneShot(clip, volume); }
    public static AudioSource Play3DStatic(AudioClip clip, Vector3 pos, float volume = 1f, bool loop = false) { return Instance != null ? Instance.Play3D(clip, pos, volume, loop) : null; }
    public static void Play3DOneShotStatic(AudioClip clip, Vector3 pos, float volume = 1f) { if (Instance != null) Instance.Play3DOneShot(clip, pos, volume); }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Reflection;

[CustomEditor(typeof(Readme))]
[InitializeOnLoad]
public class ReadmeEditor : Editor
{
    static string s_ShowedReadmeSessionStateName = "ReadmeEditor.showedReadme";

    static string s_ReadmeSourceDirectory = "Assets/TutorialInfo";

    const float k_Space = 16f;

    static ReadmeEditor()
    {
        EditorApplication.delayCall += SelectReadmeAutomatically;
    }

    static void RemoveTutorial()
    {
        if (EditorUtility.DisplayDialog("Remove Readme Assets",

            $"All contents under {s_ReadmeSourceDirectory} will be removed, are you sure you want to proceed?",
            "Proceed",
            "Cancel"))
        {
            if (Directory.Exists(s_ReadmeSourceDirectory))
            {
                FileUtil.DeleteFileOrDirectory(s_ReadmeSourceDirectory);
                FileUtil.DeleteFileOrDirectory(s_ReadmeSourceDirectory + ".meta");
            }
            else
            {
                Debug.Log($"Could not find the Readme folder at {s_ReadmeSourceDirectory}");
            }

            var readmeAsset = SelectReadme();
            if (readmeAsset != null)
            {
                var path = AssetDatabase.GetAssetPath(readmeAsset);
                FileUtil.DeleteFileOrDirectory(path + ".meta");
                FileUtil.DeleteFileOrDirectory(path);
            }

            AssetDatabase.Refresh();
        }
    }

    static void SelectReadmeAutomatically()
    {
        if (!SessionState.GetBool(s_ShowedReadmeSessionStateName, false))
        {
            var readme = SelectReadme();
            SessionState.SetBool(s_ShowedReadmeSessionStateName, true);

            if (readme && !readme.loadedLayout)
            {
                LoadLayout();
                readme.loadedLayout = true;
            }
        }
    }

    static void LoadLayout()
    {
        var assembly = typeof(EditorApplication).Assembly;
        var windowLayoutType = assembly.GetType("UnityEditor.WindowLayout", true);
        var method = windowLayoutType.GetMethod("LoadWindowLayout", BindingFlags.Public | BindingFlags.Static);
        method.Invoke(null, new object[] { Path.Combine(Application.dataPath, "TutorialInfo/Layout.wlt"), false });
    }

    static Readme SelectReadme()
    {
        var ids = AssetDatabase.FindAssets("Readme t:Readme");
        if (ids.Length == 1)
        {
            var readmeObject = AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(ids[0]));

            Selection.objects = new UnityEngine.Object[] { readmeObject };

            return (Readme)readmeObject;
        }
        else
        {
            Debug.Log("Couldn't find a readme");
            return null;
        }
    }

    protected override void OnHeaderGUI()
    {
        var readme = (Readme)target;
        Init();

        var iconWidth = Mathf.Min(EditorGUIUtility.currentViewWidth / 3f - 20f, 128f);

        GUILayout.BeginHorizontal("In BigTitle");
        {
            if (readme.icon != null)
            {
                GUILayout.Space(k_Space);
                GUILayout.Label(readme.icon, GUILayout.Width(iconWidth), GUILayout.Height(iconWidth));
            }
            GUILayout.Space(k_Space);
            GUILayout.BeginVertical();
            {

                GUILayout.FlexibleSpace();
                GUILayout.Label(readme.title, TitleStyle);
                GUILayout.FlexibleSpace();
            }
            GUILayout.EndVertical();
            GUILayout.FlexibleSpace();
        }
        GUILayout.EndHorizontal();
    }

    public override void OnInspectorGUI()
    {
        var readme = (Readme)target;
        Init();

        foreach (var section in readme.sections)
        {
            if (!string.IsNullOrEmpty(section.heading))
            {
                GUILayout.Label(section.heading, HeadingStyle);
            }

            if (!string.IsNullOrEmpty(section.text))
            {
                GUILayout.Label(section.text, BodyStyle);
            }

            if (!string.IsNullOrEmpty(section.linkText))
            {
                if (LinkLabel(new GUIContent(section.linkText)))
                {
                    Application.OpenURL(section.url);
                }
            }

            GUILayout.Space(k_Space);
        }

        if (GUILayout.Button("Remove Readme Assets", ButtonStyle))
        {
            RemoveTutorial();
        }
    }

    bool m_Initialized;

    GUIStyle LinkStyle
    {
        get { return m_LinkStyle; }
    }

    [SerializeField]
    GUIStyle m_LinkStyle;

    GUIStyle TitleStyle
    {
        get { return m_TitleStyle; }
    }

    [SerializeField]
    GUIStyle m_TitleStyle;

    GUIStyle HeadingStyle
    {
        get { return m_HeadingStyle; }
    }

    [SerializeField]
    GUIStyle m_HeadingStyle;

    GUIStyle BodyStyle
    {
        get { return m_BodyStyle; }
    }

    [SerializeField]
    GUIStyle m_BodyStyle;

    GUIStyle ButtonStyle
    {
        get { return m_ButtonStyle; }
    }

    [SerializeField]
    GUIStyle m_ButtonStyle;

    void Init()
    {
        if (m_Initialized)
            return;
        m_BodyStyle = new GUIStyle(EditorStyles.label);
        m_BodyStyle.wordWrap = true;
        m_BodyStyle.fontSize = 14;
        m_BodyStyle.richText = true;

        m_TitleStyle = new GUIStyle(m_BodyStyle);
        m_TitleStyle.fontSize = 26;

        m_HeadingStyle = new GUIStyle(m_BodyStyle);
        m_HeadingStyle.fontStyle = FontStyle.Bold;
        m_HeadingStyle.fontSize = 18;

        m_LinkStyle = new GUIStyle(m_BodyStyle);
        m_LinkStyle.wordWrap = false;

        // Match selection color which works nicely for both light and dark skins
        m_LinkStyle.normal.textColor = new Color(0x00 / 255f, 0x78 / 255f, 0xDA / 255f, 1f);
        m_LinkStyle.stretchWidth = false;

        m_ButtonStyle = new GUIStyle(EditorStyles.miniButton);
        m_ButtonStyle.fontStyle = FontStyle.Bold;

        m_Initialized = true;
    }

    bool LinkLabel(GUIContent label, params GUILayoutOption[] options)
    {
        var position = GUILayoutUtility.GetRect(label, LinkStyle, options);

        Handles.BeginGUI();
        Handles.color = LinkStyle.normal.textColor;
        Handles.DrawLine(new Vector3(position.xMin, position.yMax), new Vector3(position.xMax, position.yMax));
        Handles.color = Color.white;
        Handles.EndGUI();

        EditorGUIUtility.AddCursorRect(position, MouseCursor.Link);

        return GUI.Button(position, label, LinkStyle);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Reflection;

namespace TutorialInfo.Scripts.Editor
{
    [CustomEditor(typeof(Readme))]
    [InitializeOnLoad]
    public class ReadmeEditor : UnityEditor.Editor
    {
    static string s_ShowedReadmeSessionStateName = "ReadmeEditor.showedReadme";

    static string s_ReadmeSourceDirectory = "Assets/TutorialInfo";

    const float k_Space = 16f;

    static ReadmeEditor()
    {
        EditorApplication.delayCall += SelectReadmeAutomatically;
    }

    static void RemoveTutorial()
    {
        if (EditorUtility.DisplayDialog("Remove Readme Assets",

            $"All contents under {s_ReadmeSourceDirectory} will be removed, are you sure you want to proceed?",
            "Proceed",
            "Cancel"))
        {
            if (Directory.Exists(s_ReadmeSourceDirectory))
            {
                FileUtil.DeleteFileOrDirectory(s_ReadmeSourceDirectory);
                FileUtil.DeleteFileOrDirectory(s_ReadmeSourceDirectory + ".meta");
            }
            else
            {
                Debug.Log($"Could not find the Readme folder at {s_ReadmeSourceDirectory}");
            }

            var readmeAsset = SelectReadme();
            if (readmeAsset != null)
            {
                var path = AssetDatabase.GetAssetPath(readmeAsset);
                FileUtil.DeleteFileOrDirectory(path + ".meta");
                FileUtil.DeleteFileOrDirectory(path);
            }

            AssetDatabase.Refresh();
        }
    }

    static void SelectReadmeAutomatically()
    {
        if (!SessionState.GetBool(s_ShowedReadmeSessionStateName, false))
        {
            var readme = SelectReadme();
            SessionState.SetBool(s_ShowedReadmeSessionStateName, true);

            if (readme && !readme.loadedLayout)
            {
                LoadLayout();
                readme.loadedLayout = true;
            }
        }
    }

    static void LoadLayout()
    {
        var assembly = typeof(EditorApplication).Assembly;
        var windowLayoutType = assembly.GetType("UnityEditor.WindowLayout", true);
        var method = windowLayoutType.GetMethod("LoadWindowLayout", BindingFlags.Public | BindingFlags.Static);
        if (method != null)
        {
            try
            {
                method.Invoke(null, new object[] { Path.Combine(Application.dataPath, "TutorialInfo/Layout.wlt"), false });
            }
            catch (System.Exception ex)
            {
                Debug.LogWarning($"Could not load layout: {ex.Message}");
            }
        }
        else
        {
            Debug.LogWarning("WindowLayout.LoadWindowLayout method not found via reflection.");
        }
    }

    static Readme SelectReadme()
    {
        var ids = AssetDatabase.FindAssets("Readme t:Readme");
        if (ids.Length == 1)
        {
            var readmeObject = AssetDatabase.LoadMainAssetAtPath(AssetDatabase.GUIDToAssetPath(ids[0]));

            Selection.objects = new[] { readmeObject };
            return (Readme)readmeObject;
        }
        else
        {
            Debug.Log("Couldn't find a readme");
            return null;
        }
    }

    protected override void OnHeaderGUI()
    {
        var readme = (Readme)target;
        Init();

        var iconWidth = Mathf.Min(EditorGUIUtility.currentViewWidth / 3f - 20f, 128f);

        GUILayout.BeginHorizontal("In BigTitle");
        {
            if (readme.icon != null)
            {
                GUILayout.Space(k_Space);
                GUILayout.Label(readme.icon, GUILayout.Width(iconWidth), GUILayout.Height(iconWidth));
            }
            GUILayout.Space(k_Space);
            GUILayout.BeginVertical();
            {

                GUILayout.FlexibleSpace();
                GUILayout.Label(readme.title, TitleStyle);
                GUILayout.FlexibleSpace();
            }
            GUILayout.EndVertical();
            GUILayout.FlexibleSpace();
        }
        GUILayout.EndHorizontal();
    }

    public override void OnInspectorGUI()
    {
        var readme = (Readme)target;
        Init();

        foreach (var section in readme.sections)
        {
            if (!string.IsNullOrEmpty(section.heading))
            {
                GUILayout.Label(section.heading, HeadingStyle);
            }

            if (!string.IsNullOrEmpty(section.text))
            {
                GUILayout.Label(section.text, BodyStyle);
            }

            if (!string.IsNullOrEmpty(section.linkText))
            {
                if (LinkLabel(new GUIContent(section.linkText)))
                {
                    Application.OpenURL(section.url);
                }
            }

            GUILayout.Space(k_Space);
        }

        if (GUILayout.Button("Remove Readme Assets", ButtonStyle))
        {
            RemoveTutorial();
        }
    }

    bool m_Initialized;

    GUIStyle LinkStyle
    {
        get { return m_LinkStyle; }
    }

    [SerializeField]
    GUIStyle m_LinkStyle;

    GUIStyle TitleStyle
    {
        get { return m_TitleStyle; }
    }

    [SerializeField]
    GUIStyle m_TitleStyle;

    GUIStyle HeadingStyle
    {
        get { return m_HeadingStyle; }
    }

    [SerializeField]
    GUIStyle m_HeadingStyle;

    GUIStyle BodyStyle
    {
        get { return m_BodyStyle; }
    }

    [SerializeField]
    GUIStyle m_BodyStyle;

    GUIStyle ButtonStyle
    {
        get { return m_ButtonStyle; }
    }

    [SerializeField]
    GUIStyle m_ButtonStyle;

    void Init()
    {
        if (m_Initialized)
            return;
        m_BodyStyle = new GUIStyle(EditorStyles.label);
        m_BodyStyle.wordWrap = true;
        m_BodyStyle.fontSize = 14;
        m_BodyStyle.richText = true;

        m_TitleStyle = new GUIStyle(m_BodyStyle);
        m_TitleStyle.fontSize = 26;

        m_HeadingStyle = new GUIStyle(m_BodyStyle);
        m_HeadingStyle.fontStyle = FontStyle.Bold;
        m_HeadingStyle.fontSize = 18;

        m_LinkStyle = new GUIStyle(m_BodyStyle);
        m_LinkStyle.wordWrap = false;

        // Match selection color which works nicely for both light and dark skins
        m_LinkStyle.normal.textColor = new Color(0x00 / 255f, 0x78 / 255f, 0xDA / 255f, 1f);
        m_LinkStyle.stretchWidth = false;

        m_ButtonStyle = new GUIStyle(EditorStyles.miniButton);
        m_ButtonStyle.fontStyle = FontStyle.Bold;

        m_Initialized = true;
    }

    bool LinkLabel(GUIContent label, params GUILayoutOption[] options)
    {
        var position = GUILayoutUtility.GetRect(label, LinkStyle, options);

        Handles.BeginGUI();
        Handles.color = LinkStyle.normal.textColor;
        Handles.DrawLine(new Vector3(position.xMin, position.yMax), new Vector3(position.xMax, position.yMax));
        Handles.color = Color.white;
        Handles.EndGUI();

        EditorGUIUtility.AddCursorRect(position, MouseCursor.Link);

        return GUI.Button(position, label, LinkStyle);
    }
}

}
